// Builds the Apps Script copies the engine project needs, from the single
// sources in this repo. Run before every push (the guarded deploy runs it):
//
//   node scripts/ee-sync.mjs           write email-engine/src/Lib_*.js and Seed.js
//   node scripts/ee-sync.mjs --check   exit 1 if any generated file is stale
//
// Apps Script can't import files, so the shared modules (also used by the
// portal and Vercel) are copied verbatim, with a header recording the source's
// sha256. tests/email-engine-sync.test.js runs --check, so drift fails the suite.
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const SRC = path.join(ROOT, 'email-engine', 'src');
const sha = t => crypto.createHash('sha256').update(t).digest('hex');
const read = rel => fs.readFileSync(path.join(ROOT, rel), 'utf8');

const outputs = {};
for (const [lib, out] of [['js/lib/lifecycle-rules.js', 'Lib_LifecycleRules.js'], ['js/lib/email-render.js', 'Lib_EmailRender.js'],
  ['js/lib/email-tracking.js', 'Lib_EmailTracking.js'], ['js/lib/batches.js', 'Lib_Batches.js']]) {
  const text = read(lib);
  outputs[out] = `// GENERATED by scripts/ee-sync.mjs from ${lib} (sha256 ${sha(text)}). Do not edit; edit the source.\n` + text;
}
const json = rel => { const o = JSON.parse(read(rel)); delete o._comment; return o; };
const content = json('email-engine/seed/content-bc.json');
const templates = {};
for (const s of Object.values(content.steps)) templates[s.body] = read(path.join('email-engine/templates', s.body));
for (const b of Object.values(content.blocks)) templates[b.html] = read(path.join('email-engine/templates', b.html));
const seed = { ruleset: json('email-engine/seed/ruleset-bc.json'), fields: json('email-engine/seed/fields.json').fields,
  config: json('email-engine/seed/config.json'), content, templates };
outputs['Seed.js'] = '// GENERATED by scripts/ee-sync.mjs from email-engine/seed/*.json and email-engine/templates/. Do not edit.\n' +
  'var EE_SEED = ' + JSON.stringify(seed, null, 2) + ';\n';

const check = process.argv.includes('--check');
let stale = [];
for (const [name, text] of Object.entries(outputs)) {
  const file = path.join(SRC, name);
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (current === text) continue;
  if (check) stale.push(name); else { fs.writeFileSync(file, text); console.log('wrote', path.relative(ROOT, file)); }
}
if (check && stale.length) { console.error('stale generated files: ' + stale.join(', ') + ' (run node scripts/ee-sync.mjs)'); process.exit(1); }
if (check) console.log('generated files are up to date');
